@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-warning: var(--warning);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);
  --radius-3xl: calc(var(--radius) + 16px);
  --radius-4xl: calc(var(--radius) + 24px);
}

@layer base {
  :root {
    color-scheme: light;
    --radius: 0.5rem;
    --background: oklch(1 0 0);
    --foreground: oklch(0.273 0.014 267);
    --card: oklch(1 0 0);
    --card-foreground: oklch(0.273 0.014 267);
    --popover: oklch(1 0 0);
    --popover-foreground: oklch(0.273 0.014 267);
    --primary: oklch(0.54 0.136 269);
    --primary-foreground: oklch(1 0 0);
    --secondary: oklch(0.961 0.003 264);
    --secondary-foreground: oklch(0.34 0.015 264);
    --muted: oklch(0.961 0.003 264);
    --muted-foreground: oklch(0.575 0.016 264);
    --accent: oklch(0.954 0.005 258);
    --accent-foreground: oklch(0.32 0.014 262);
    --destructive: oklch(0.563 0.175 20);
    --warning: oklch(0.649 0.137 69);
    --border: oklch(0.894 0.008 261);
    --input: oklch(0.863 0.008 261);
    --ring: oklch(0.578 0.161 267);
    --chart-1: oklch(0.646 0.222 41.116);
    --chart-2: oklch(0.6 0.118 184.704);
    --chart-3: oklch(0.398 0.07 227.392);
    --chart-4: oklch(0.828 0.189 84.429);
    --chart-5: oklch(0.769 0.188 70.08);
    --sidebar: oklch(0.985 0.002 264);
    --sidebar-foreground: oklch(0.273 0.014 267);
    --sidebar-primary: oklch(0.54 0.136 269);
    --sidebar-primary-foreground: oklch(1 0 0);
    --sidebar-accent: oklch(0.954 0.005 258);
    --sidebar-accent-foreground: oklch(0.32 0.014 262);
    --sidebar-border: oklch(0.894 0.008 261);
    --sidebar-ring: oklch(0.578 0.161 267);
  }

  :root[data-theme="dark"],
  .dark {
    color-scheme: dark;
    --background: oklch(0.17 0.006 264);
    --foreground: oklch(0.97 0.003 264);
    --card: oklch(0.205 0.007 264);
    --card-foreground: oklch(0.97 0.003 264);
    --popover: oklch(0.205 0.007 264);
    --popover-foreground: oklch(0.97 0.003 264);
    --primary: oklch(0.56 0.135 267);
    --primary-foreground: oklch(0.985 0 0);
    --secondary: oklch(0.27 0.008 264);
    --secondary-foreground: oklch(0.97 0.003 264);
    --muted: oklch(0.27 0.008 264);
    --muted-foreground: oklch(0.72 0.01 264);
    --accent: oklch(0.3 0.01 264);
    --accent-foreground: oklch(0.97 0.003 264);
    --destructive: oklch(0.7 0.16 20);
    --warning: oklch(0.78 0.13 75);
    --border: oklch(1 0 0 / 10%);
    --input: oklch(1 0 0 / 15%);
    --ring: oklch(0.6 0.14 267);
    --chart-1: oklch(0.488 0.243 264.376);
    --chart-2: oklch(0.696 0.17 162.48);
    --chart-3: oklch(0.769 0.188 70.08);
    --chart-4: oklch(0.627 0.265 303.9);
    --chart-5: oklch(0.645 0.246 16.439);
    --sidebar: oklch(0.205 0.007 264);
    --sidebar-foreground: oklch(0.97 0.003 264);
    --sidebar-primary: oklch(0.56 0.135 267);
    --sidebar-primary-foreground: oklch(0.985 0 0);
    --sidebar-accent: oklch(0.27 0.008 264);
    --sidebar-accent-foreground: oklch(0.97 0.003 264);
    --sidebar-border: oklch(1 0 0 / 10%);
    --sidebar-ring: oklch(0.6 0.14 267);
  }

  * {
    border-color: var(--border);
    outline-color: color-mix(in oklab, var(--ring) 50%, transparent);
  }

  body {
    color: var(--foreground);
    background: var(--background);
  }
}
